@GameTestHolder(HeavenlyRestriction.ID) @PrefixGameTestTemplate(false)
public final class ExponentiationGameTests {
    private static ManasSkillInstance equip(LivingEntity p){RestrictionData.learnReward(p,HeavenlyRestriction.EXPONENTIATION.get());var i=SkillAPI.getSkillsFrom(p).getSkill(HeavenlyRestriction.EXPONENTIATION.get()).orElseThrow();i.setMastery(0);TensuraStorages.getAbilityFrom(p).setAbilitySlot(0,0,i.getSkill(),0);return i;}
    private static void reset(ServerPlayer p,Runnable task){try(var scope=ExponentiationContext.raw(p,ExponentiationContext.RESTORE)){task.run();}}
    @GameTest(template="empty",timeoutTicks=100)
    public static void activePresetLearningAndTemporaryStatsAreExact(GameTestHelper h){var p=player(h);p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);var i=equip(p);h.assertTrue(Exponentiation.active(p),"Slotted learned skill inactive");for(int n=0;n<30;n++)near(h,p.getMaxHealth(),10000,"Repeated stat reads compounded");near(h,p.getAttribute(Attributes.MAX_HEALTH).getBaseValue(),100,"Saved base was mutated");TensuraStorages.getAbilityFrom(p).setAbilitySlot(0,0,null,0);near(h,p.getMaxHealth(),100,"Unslotted bonus remained");TensuraStorages.getAbilityFrom(p).setAbilitySlot(1,0,i.getSkill(),0);h.assertTrue(!Exponentiation.active(p),"Inactive preset activated passive");TensuraStorages.getAbilityFrom(p).setAbilitySlot(0,0,i.getSkill(),0);i.setMastery(-1);h.assertTrue(!Exponentiation.active(p),"Unlearned passive activated");h.assertTrue(!ChainedReincarnation.blocked(i.getSkill(),p),"No-cost skill incorrectly blacklisted");h.assertTrue(io.github.manasmods.tensura.menu.ReincarnationMenu.getSkillPool().contains(i.getSkill()),"Reincarnation pool missing Exponentiation");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void nonMovementSpeedsAreSquaredAndMovementIsUntouched(GameTestHelper h){var p=player(h);p.getAttribute(Attributes.ATTACK_SPEED).setBaseValue(4);p.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(.25);p.getAttribute(Attributes.JUMP_STRENGTH).setBaseValue(.7);p.getAttribute(TensuraAttributes.CHANT_SPEED).setBaseValue(3);equip(p);near(h,p.getAttributeValue(Attributes.ATTACK_SPEED),16,"Attack speed excluded");near(h,p.getAttributeValue(TensuraAttributes.CHANT_SPEED),9,"Chant speed excluded");near(h,p.getAttributeValue(Attributes.MOVEMENT_SPEED),.25,"Movement speed changed");near(h,p.getAttributeValue(Attributes.JUMP_STRENGTH),.7,"Jump changed");p.setOnGround(true);p.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.DIAMOND_PICKAXE));float speed;try(var scope=ExponentiationContext.raw(p,ExponentiationContext.RESTORE)){TensuraStorages.getAbilityFrom(p).setAbilitySlot(0,0,null,0);speed=p.getDigSpeed(Blocks.STONE.defaultBlockState(),p.blockPosition());TensuraStorages.getAbilityFrom(p).setAbilitySlot(0,0,HeavenlyRestriction.EXPONENTIATION.get(),0);}near(h,p.getDigSpeed(Blocks.STONE.defaultBlockState(),p.blockPosition()),speed*speed,"Final mining speed was not squared once");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void realMeleeAndSkillDamageSquareOnceAndOnlyForTheAttacker(GameTestHelper h){var p=player(h);var e=target(h,p.position().add(2,0,0));e.getAttribute(Attributes.ARMOR).setBaseValue(0);p.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(10);equip(p);reset(p,()->p.setHealth(20));float before=e.getHealth();e.invulnerableTime=0;e.hurt(p.damageSources().playerAttack(p),10);near(h,before-e.getHealth(),100,"Flat skill damage square");e.setHealth(1024);e.invulnerableTime=0;try(var scope=ExponentiationContext.raw(p,ExponentiationContext.DAMAGE)){near(h,p.getAttributeValue(Attributes.ATTACK_DAMAGE),10,"Formula inputs were already squared");}p.setSprinting(false);p.setOnGround(true);try{var field=LivingEntity.class.getDeclaredField("attackStrengthTicker");field.setAccessible(true);field.setInt(p,100);}catch(ReflectiveOperationException failure){throw new IllegalStateException(failure);};p.attack(e);near(h,1024-e.getHealth(),100,"Native melee double-dipped attack attribute");var receiving=target(h,p.position().add(5,0,0));equip(receiving);float hp=receiving.getHealth();receiving.hurt(receiving.damageSources().genericKill(),3);near(h,hp-receiving.getHealth(),3,"Unattributed incoming damage was squared");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void hpShpAndEnergyGainsAreDeltasWithNormalCosts(GameTestHelper h){var p=player(h);p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);p.getAttribute(TensuraAttributes.MAX_SPIRITUAL_HEALTH).setBaseValue(100);equip(p);var energy=TensuraStorages.getExistenceFrom(p);reset(p,()->{p.setHealth(20);energy.setSpiritualHealth(20);energy.setAura(1000);energy.setMagicule(1000);});p.heal(5);near(h,p.getHealth(),45,"HP healing was not 5²");energy.setSpiritualHealth(25);near(h,energy.getSpiritualHealth(),45,"SHP healing was not 5²");energy.setAura(1005);near(h,energy.getAura(),1025,"Aura gain was not a delta");energy.setMagicule(1005);near(h,energy.getMagicule(),1025,"Magicule gain was not a delta");EnergyHelper.isOutOfEnergy(p,10,20);near(h,energy.getAura(),1015,"Aura bill changed");near(h,energy.getMagicule(),1005,"Magicule bill changed");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void healingAfterSchemaAndUnequipCleanupDoNotCompound(GameTestHelper h){var p=player(h);p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);equip(p);RestrictionData.learnReward(p,HeavenlyRestriction.SCHEMA.get());var schema=SkillAPI.getSkillsFrom(p).getSkill(HeavenlyRestriction.SCHEMA.get()).orElseThrow();schema.setMastery(0);h.assertTrue(SchemaArt.save(p,new int[]{3,0,0,0,0,0},0),"Schema build failed");schema.onToggleOn(p);reset(p,()->p.setHealth(20));p.heal(10);near(h,p.getHealth(),164,"Schema's final 12 healing must become 144");Exponentiation.tick(new net.neoforged.neoforge.event.tick.EntityTickEvent.Post(p));TensuraStorages.getAbilityFrom(p).setAbilitySlot(0,0,null,0);Exponentiation.tick(new net.neoforged.neoforge.event.tick.EntityTickEvent.Post(p));near(h,p.getHealth(),100,"Unequip retained over-cap HP");near(h,p.getAttribute(Attributes.MAX_HEALTH).getBaseValue(),100,"Cleanup changed base");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void directSpiritualDamageUsesFinalResistedAmount(GameTestHelper h){var p=player(h);var target=target(h,p.position().add(2,0,0));var energy=TensuraStorages.getExistenceFrom(target);target.getAttribute(TensuraAttributes.MAX_SPIRITUAL_HEALTH).setBaseValue(10000);energy.setSpiritualHealth(10000);equip(p);boolean hit=io.github.manasmods.tensura.damage.TensuraDamageHelper.directSpiritualHurt(target,p,p.damageSources().playerAttack(p),20,.5f);h.assertTrue(hit,"Direct spiritual attack failed");near(h,energy.getSpiritualHealth(),9900,"20 × 50% resistance should become 10², not 20²");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void chanceLimitsFractionsAndCooldownsAreRetained(GameTestHelper h){var p=player(h);equip(p);p.getAttribute(TensuraAttributes.AUTO_MELEE_DODGE_CHANCE).setBaseValue(20);p.getAttribute(TensuraAttributes.GRAVITY_BOOST).setBaseValue(3);near(h,p.getAttributeValue(TensuraAttributes.AUTO_MELEE_DODGE_CHANCE),100,"Dodge chance exceeded 100%");near(h,p.getAttributeValue(TensuraAttributes.GRAVITY_BOOST),9,"Gravity elemental damage was mistaken for movement");near(h,Exponentiation.square(.5),.5,"Beneficial-only lens reduced a fraction");var i=SkillAPI.getSkillsFrom(p).getSkill(HeavenlyRestriction.EXPONENTIATION.get()).orElseThrow();i.setCoolDown(200,0);h.assertTrue(i.getCoolDown(0)==200,"Cooldown changed");h.assertTrue(Double.isFinite(Exponentiation.square(Double.MAX_VALUE)),"Overflow reached infinity");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void learningMasteryXpAndLootAreFinalGains(GameTestHelper h){var p=player(h);equip(p);SchemaArt.discover(p);var i=SkillAPI.getSkillsFrom(p).getSkill(HeavenlyRestriction.SCHEMA.get()).orElseThrow();HeavenlyRestriction.SCHEMA.get().addLearnPoint(i,p,0,3);near(h,i.getMastery(),-991,"Learning gain not 3²");i.setMastery(0);HeavenlyRestriction.SCHEMA.get().addMasteryPoint(i,p,3);near(h,i.getMastery(),9,"Mastery gain not 3²");var xp=new net.neoforged.neoforge.event.entity.player.PlayerXpEvent.XpChange(p,3);ExponentiationRewards.xp(xp);h.assertTrue(xp.getAmount()==9,"XP gain not squared");var item=new net.minecraft.world.entity.item.ItemEntity(h.getLevel(),p.getX(),p.getY(),p.getZ(),new ItemStack(Items.COAL,5));var drops=new ArrayList<net.minecraft.world.entity.item.ItemEntity>();drops.add(item);ExponentiationRewards.block(new net.neoforged.neoforge.event.level.BlockDropsEvent(h.getLevel(),p.blockPosition(),Blocks.COAL_ORE.defaultBlockState(),null,drops,p,new ItemStack(Items.DIAMOND_PICKAXE)));h.assertTrue(item.getItem().getCount()==25,"Final loot stack was not squared");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void epPayoutSquaresEachFinalPoolAwardOnce(GameTestHelper h){var p=player(h);var victim=target(h,p.position().add(3,0,0));p.getAttribute(TensuraAttributes.AURA_GAIN).setBaseValue(100);p.getAttribute(TensuraAttributes.MAGICULE_GAIN).setBaseValue(100);double a=EnergyHelper.getBaseMaxAura(p),m=EnergyHelper.getBaseMaxMagicule(p);io.github.manasmods.tensura.handler.DeathHandler.gainEPEntity(p,victim,30);double da=EnergyHelper.getBaseMaxAura(p)-a,dm=EnergyHelper.getBaseMaxMagicule(p)-m;p.getAttribute(TensuraAttributes.MAX_AURA).setBaseValue(a);p.getAttribute(TensuraAttributes.MAX_MAGICULE).setBaseValue(m);equip(p);io.github.manasmods.tensura.handler.DeathHandler.gainEPEntity(p,victim,30);near(h,EnergyHelper.getBaseMaxAura(p)-a,Exponentiation.square(da),"Aura award compounded gain multiplier");near(h,EnergyHelper.getBaseMaxMagicule(p)-m,Exponentiation.square(dm),"Magicule award compounded gain multiplier");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void exportExactAttributePolicyAndVerifyMovementExclusions(GameTestHelper h){var rows=new com.google.gson.JsonArray();for(var entry:BuiltInRegistries.ATTRIBUTE.entrySet()){var a=entry.getValue();var rule=Exponentiation.rule(a);var row=new com.google.gson.JsonObject();row.addProperty("id",entry.getKey().location().toString());row.addProperty("name",a.getDescriptionId());row.addProperty("included",rule.included());row.addProperty("role",rule.role());row.addProperty("reason",rule.exclusion());row.addProperty("can_change",rule.included() && (!(a instanceof RangedAttribute r) || r.getMaxValue()>1));rows.add(row);}try{var file=java.nio.file.Path.of(System.getProperty("java.io.tmpdir"),"exponentiation-attribute-audit.json");java.nio.file.Files.writeString(file,new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(rows));}catch(java.io.IOException failure){throw new IllegalStateException(failure);}h.assertTrue(!Exponentiation.rule(Attributes.MOVEMENT_SPEED.value()).included() && !Exponentiation.rule(Attributes.SNEAKING_SPEED.value()).included() && Exponentiation.rule(Attributes.ATTACK_SPEED.value()).included(),"Speed exclusion policy differs from requested movement-only rule");h.succeed();}
    private static void regen(String method,Class<?>[] types,Object... args){try{var m=io.github.manasmods.tensura.storage.ep.ExistenceStorage.class.getDeclaredMethod(method,types);m.setAccessible(true);m.invoke(null,args);}catch(ReflectiveOperationException failure){throw new IllegalStateException(failure);}}
    @GameTest(template="empty",timeoutTicks=100)
    public static void nativeRegenerationAndSleepSquareOnlyTheCompletedGain(GameTestHelper h){var p=player(h);p.getAttribute(TensuraAttributes.MAX_AURA).setBaseValue(1000);p.getAttribute(TensuraAttributes.MAX_SPIRITUAL_HEALTH).setBaseValue(1000);p.getAttribute(TensuraAttributes.AURA_REGENERATION_MULTIPLIER).setBaseValue(3);p.getAttribute(TensuraAttributes.SPIRITUAL_HEALTH_REGENERATION).setBaseValue(3);equip(p);var energy=TensuraStorages.getExistenceFrom(p);double base=EnergyHelper.CONFIG.baseAuraRegen,sleep=EnergyHelper.CONFIG.sleepModeAura;try{EnergyHelper.CONFIG.baseAuraRegen=2;EnergyHelper.CONFIG.sleepModeAura=.01;reset(p,()->{energy.setAura(1000);energy.setSpiritualHealth(1000);});regen("handleAuraRegen",new Class<?>[]{io.github.manasmods.tensura.storage.ep.IExistence.class,LivingEntity.class,double.class},energy,p,EnergyHelper.getMaxAura(p));near(h,energy.getAura(),1036,"Native 2 × 3 aura regen did not become 36");energy.setSleepModeTime(200);reset(p,()->energy.setAura(1000));regen("handleAuraRegen",new Class<?>[]{io.github.manasmods.tensura.storage.ep.IExistence.class,LivingEntity.class,double.class},energy,p,EnergyHelper.getMaxAura(p));near(h,energy.getAura(),1256,"Sleep reused squared maximum and squared it twice");regen("handleSpiritualHealthRegen",new Class<?>[]{net.minecraft.server.MinecraftServer.class,LivingEntity.class,io.github.manasmods.tensura.storage.ep.IExistence.class},p.server,p,energy);near(h,energy.getSpiritualHealth(),1009,"Native SHP regen compounded or clamped to an unboosted maximum");}finally{EnergyHelper.CONFIG.baseAuraRegen=base;EnergyHelper.CONFIG.sleepModeAura=sleep;}h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void fusionTransfersDoNotBecomeHealingOrResquareCapacity(GameTestHelper h){var p=player(h);var host=target(h,p.position().add(3,0,0));p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);host.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);equip(p);RestrictionData.learnReward(p,HeavenlyRestriction.FUSION.get());TensuraStorages.getExistenceFrom(host).setPermanentOwner(p.getUUID());reset(p,()->p.setHealth(50));host.setHealth(50);double ep=EnergyHelper.getMaxEP(p)+EnergyHelper.getMaxEP(host);afterTracking(h,List.of(host),()->{try(var nativeCallback=ChainedContext.ability(p,HeavenlyRestriction.FUSION.get())){h.assertTrue(dev.heavenlyrestriction.fusion.Fusion.fuseSubordinate(p,host),"Fusion failed");}try{near(h,p.getMaxHealth(),10100,"Fusion capacity squared twice");near(h,p.getHealth(),100,"Transferred HP was interpreted as healing");double actual=EnergyHelper.getMaxEP(p),expected=1.5*ep;h.assertTrue(Math.abs(actual-expected)/expected<1e-6,"Fusion EP solver compounded Exponentiation");}finally{try(var nativeCallback=ChainedContext.ability(p,HeavenlyRestriction.FUSION.get())){dev.heavenlyrestriction.fusion.Fusion.end(p,"Test");}}near(h,p.getMaxHealth(),10000,"Fusion permanently changed capacity");h.succeed();});}

}
